head.script:
scwin.setSimulate = function() {
    WebSquare.wUnit.getJq('.w2editablePivot_cell.type8.pvtVal.row0.col0').simulate('keydown', {
        keyCode: 46,
        which: 46,
        key: 'delete'
    });
}
scwin.setSimulate2 = function() {
    WebSquare.wUnit.getJq('.w2editablePivot_cell.type8.pvtVal.row0.col2').simulate('key-combo', {
        combo: 'ctrl+z'
    });
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('.w2editablePivot_cell.type8.pvtVal.row0.col2').text() != '';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('.w2editablePivot_cell.type8.pvtVal.row0.col1').text() != '';
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('.w2editablePivot_cell.type8.pvtVal.row0.col0').text() != '';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2editablePivot_cell.type8.pvtVal.row0.col0').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2editablePivot_cell.type8.pvtVal.row0.col1').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2editablePivot_cell.type8.pvtVal.row0.col2').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand('pause', '500');
    //Verify step 1
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.inputData = [];
    window.areaArr = ["전국", "서울특별시", "부산광역시", "대전광역시", "대구광역시", "광주광역시", "울산광역시", "수원시", "창원시", "과천시"];
    window.categoryArr = ["제조업", "공업", "경공업", "중공업", "수공업", "어업", "광업", "농업", "낙농업", "원예농업"];
    window.periodArr = ["2006년", "2007년", "2008년", "2009년", "2010년", "2011년", "2012년", "2013년", "2014년", "2015년"];
    window.typeArr = ["갑", "을", "병", "정", "무", "기", "경", "신", "임", "계"];
    window.rankArr = ["A+등급", "B+등급", "C+등급", "D+등급", "A등급", "B등급", "C등급", "D등급", "A-등급", "B-등급", ];
    for (var i = 0; i < 10; i++) {
        for (var j = 0; j < 10; j++) {
            for (var k = 0; k < 10; k++) {
                for (var l = 0; l < 10; l++) {
                    for (var m = 0; m < 10; m++) {
                        inputData.push({
                            cat1: areaArr[i],
                            cat2: categoryArr[j],
                            cat3: periodArr[k],
                            cat4: typeArr[l],
                            cat5: rankArr[m],
                            val1: Math.ceil(Math.random() * 100),
                            val2: Math.ceil(Math.random() * 1000),
                            val3: Math.ceil(Math.random() * 10),
                            val4: Math.ceil(Math.random() * 10000),
                            val5: Math.ceil(Math.random() * 100)
                        })
                    }
                }
            }
        }
    }
    window.date = new Date();
    console.log(date);
    dataList1.setJSON(inputData);
    window.date2 = new Date();
    console.log(date2 - date);
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
